brokenCode.code:
let n = 0;
function spin() {
  n++;
  Promise.resolve().then(spin); // keeps scheduling microtasks forever
}
spin();
setTimeout(() => console.log('timer fired', n), 0);
// 'timer fired' is never logged

solution.code:
let n = 0;
function spin() {
  n++;
  if (n < 5) setTimeout(spin, 0); // macrotask yields between iterations
}
spin();
setTimeout(() => console.log('timer fired', n), 0);
// the loop now interleaves tasks, so the timer fires

console.log('1');
setTimeout(() => console.log('2'), 0);
Promise.resolve()
  .then(() => console.log('3'))
  .then(() => console.log('4'));
console.log('5');

// Output:
// 1   (sync)
// 5   (sync)
// 3   (microtask)
// 4   (microtask chained, same drain)
// 2   (macrotask)
